import React, { useRef } from "react";
import { useReactToPrint } from "react-to-print";
import DashboardNavbar from "../../Components/User/DashboardNavbar";
import Sidebar from "../../Components/User/Sidebar";
import axios from "axios"; // Import axios for API calls

const Certificate = ({ studentName, courseName, date, certificateId }) => {
  console.log("Certificate ID:", certificateId); // Debugging line
  const certificateRef = useRef();

  const handlePrint = useReactToPrint({
    content: () => certificateRef.current,
    documentTitle: `${studentName}_Certificate`,
  });

  // Function to download the certificate as a PDF
  const handleDownload = async () => {
    try {
      const response = await axios.get(
        `/api/certificates/${certificateId}/download`,
        {
          responseType: "blob", // Important for downloading files
        }
      );

      // Create a URL for the blob
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `${studentName}_Certificate.pdf`); // Set the file name
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link); // Clean up
    } catch (error) {
      console.error("Error downloading certificate:", error);
    }
  };

  return (
    <div>
      <DashboardNavbar />
      <Sidebar />

      <div className="flex items-center justify-center min-h-[70vh] bg-transparent ">
        <div
          ref={certificateRef}
          className="bg-white border-4 shadow-lg rounded-xl p-10 w-[600px] text-center"
          style={{ borderColor: "#FFD700" }}
        >
          <h1 className="text-4xl font-bold" style={{ color: "#FFD700" }}>
            Certificate of Completion
          </h1>

          <p className="text-lg text-gray-700 mt-4">
            This is proudly presented to
          </p>
          <h2 className="text-3xl font-semibold text-gray-900 mt-2">
            {studentName}
          </h2>
          <p className="text-lg text-gray-700 mt-4">
            For successfully completing the course
          </p>
          <h3 className="text-2xl font-semibold text-gray-900 mt-2">
            {courseName}
          </h3>
          <p className="text-md text-gray-600 mt-4">
            Date of Completion: {date}
          </p>
          <div className="mt-6 flex justify-between px-8">
            <div className="text-left">
              <p className="text-gray-700 font-semibold">ELearnOfficial</p>
              <div className="h-[2px] w-32 bg-gray-500 mt-2"></div>
            </div>
            <div className="text-right">
              <p className="text-gray-700 font-semibold">Signature</p>
              <div className="h-[2px] w-32 bg-gray-500 mt-2"></div>
            </div>
          </div>

          {/* Add Download and Print Buttons */}
          <div className="mt-8 flex justify-center space-x-4">
            <button
              onClick={handleDownload}
              className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
            >
              Download PDF
            </button>
            <button
              onClick={handlePrint}
              className="bg-yellow-500 text-white px-4 py-2 rounded hover:bg-green-600"
            >
              Print Certificate
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Certificate;
